1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <title>Pulsing Circle</title>
9	  <style>
10	    :root {
11	      --circle-hue: #8ec5ff;
12	      --circle-core: #4a7dd9;
13	      --circle-shadow: #1f3a75;
14	      --cycle: 2.5s;
15	    }
16	    * {
17	      margin: 0;
18	      padding: 0;
19	      box-sizing: border-box;
20	    }
21	    body {
22	      width: 100vw;
23	      height: 100vh;
24	      height: 100dvh;
25	      display: flex;
26	      flex-direction: column;
27	      justify-content: center;
28	      align-items: center;
29	      gap: 24px;
30	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
31	      overflow: hidden;
32	    }
33	    svg {
34	      width: min(400px, 80vmin);
35	      height: min(400px, 80vmin);
36	      overflow: visible;
37	      cursor: pointer;
38	      user-select: none;
39	      -webkit-tap-highlight-color: transparent;
40	      transition: filter 0.3s ease;
41	    }
42	    svg:hover {
43	      filter: brightness(1.08);
44	    }
45	    svg:focus-visible {
46	      outline: 2px solid var(--circle-hue);
47	      outline-offset: 8px;
48	      border-radius: 50%;
49	    }
50	    .ambient {
51	      fill: var(--circle-hue);
52	      opacity: 0.12;
53	      filter: blur(30px);
54	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
55	      transform-origin: 200px 200px;
56	      will-change: transform, opacity;
57	    }
58	    .core {
59	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
60	      transform-origin: 200px 200px;
61	      filter: url(#glow);
62	      will-change: transform, opacity;
63	    }
64	    .highlight {
65	      fill: url(#highlightGradient);
66	      transform-origin: 200px 200px;
67	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
68	      pointer-events: none;
69	      will-change: transform, opacity;
70	    }
71	    .ring {
72	      fill: none;
73	      stroke: var(--circle-hue);
74	      stroke-width: 2.5;
75	      transform-origin: 200px 200px;
76	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
77	      will-change: transform, opacity, stroke-width;
78	    }
79	    .ring--delay-1 {
80	      animation-delay: calc(var(--cycle) / 3);
81	    }
82	    .ring--delay-2 {
83	      animation-delay: calc(var(--cycle) / 3 * 2);
84	    }
85	    @keyframes pulse {
86	      0%, 100% {
87	        transform: scale(1);
88	        opacity: 0.9;
89	      }
90	      50% {
91	        transform: scale(1.05);
92	        opacity: 1;
93	      }
94	    }
95	    @keyframes breathe {
96	      0%, 100% {
97	        transform: scale(0.95);
98	        opacity: 0.1;
99	      }
100	      50% {
101	        transform: scale(1.1);
102	        opacity: 0.18;
103	      }
104	    }
105	    @keyframes ripple {
106	      0% {
107	        transform: scale(1);
108	        opacity: 0.6;
109	        stroke-width: 2.5;
110	      }
111	      100% {
112	        transform: scale(1.35);
113	        opacity: 0;
114	        stroke-width: 0.5;
115	      }
116	    }
117	    body.paused .core,
118	    body.paused .ring,
119	    body.paused .ambient,
120	    body.paused .highlight {
121	      animation-play-state: paused;
122	    }
123	    @media (prefers-reduced-motion: reduce) {
124	      .core, .ring, .ambient, .highlight {
125	        animation-play-state: paused;
126	      }
127	    }
128	    .speed-label {
129	      color: var(--circle-hue);
130	      font-family: system-ui, sans-serif;
131	      font-size: 0.85rem;
132	      letter-spacing: 0.05em;
133	      opacity: 0.85;
134	      user-select: none;
135	      text-align: center;
136	    }
137	    .hint {
138	      display: block;
139	      margin-top: 4px;
140	      font-size: 0.7rem;
141	      opacity: 0.85;
142	    }
143	  </style>
144	</head>
145	<body>
146	  <svg id="ae683f770" viewBox="0 0 400 400" role="button" tabindex="0" aria-label="Pulsing blue circle animation. Click or press Enter to change pulse speed. Press space to pause." aria-describedby="speedText" aria-pressed="false">
147	    <defs>
148	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
149	        <stop offset="0%" stop-color="#8ec5ff"/>
150	        <stop offset="55%" stop-color="#4a7dd9"/>
151	        <stop offset="100%" stop-color="#1f3a75"/>
152	      </radialGradient>
153	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
154	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
155	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
156	      </radialGradient>
157	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
158	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
159	        <feColorMatrix in="blur" type="matrix"
160	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
161	        <feMerge>
162	          <feMergeNode in="tintedBlur"/>
163	          <feMergeNode in="SourceGraphic"/>
164	        </feMerge>
165	      </filter>
166	    </defs>
167	    <circle class="ambient" cx="200" cy="200" r="160"/>
168	    <circle class="ring" cx="200" cy="200" r="140"/>
169	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
170	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
171	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
172	    <circle class="highlight" cx="200" cy="200" r="140"/>
173	  </svg>
174	  <p class="speed-label" id="speedLabel" aria-live="polite">
175	    <span id="speedText">Normal speed</span>
176	    <span class="hint">Click to change speed · Space to pause</span>
177	  </p>
178	  <script>
179	    const svg = document.getElementById('ae683f770');
180	    const speedText = document.getElementById('speedText');
181	    const speeds = [
182	      { value: '2.5s', name: 'Normal speed' },
183	      { value: '1.2s', name: 'Fast speed' },
184	      { value: '4.5s', name: 'Slow speed' },
185	    ];
186	    let speedIndex = 0;
187	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
188	    let manuallyPaused = reducedMotionQuery.matches;
189	
190	    function updateLabels() {
191	      const { name } = speeds[speedIndex];
192	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
193	    }
194	
195	    function cycleSpeed() {
196	      speedIndex = (speedIndex + 1) % speeds.length;
197	      const { value } = speeds[speedIndex];
198	      svg.style.setProperty('--cycle', value);
199	      // Restart animations from the beginning so the new speed feels immediate
200	      // instead of jumping mid-cycle.
201	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
202	        el.style.animation = 'none';
203	        void el.offsetWidth;
204	        el.style.animation = '';
205	      });
206	      updateLabels();
207	    }
208	
209	    function togglePause() {
210	      manuallyPaused = !manuallyPaused;
211	      document.body.classList.toggle('paused', manuallyPaused);
212	      svg.setAttribute('aria-pressed', String(manuallyPaused));
213	      updateLabels();
214	    }
215	
216	    svg.addEventListener('click', cycleSpeed);
217	    svg.addEventListener('keydown', (e) => {
218	      if (e.key === 'Enter') {
219	        e.preventDefault();
220	        cycleSpeed();
221	      } else if (e.key === ' ') {
222	        e.preventDefault();
223	        togglePause();
224	      }
225	    });
226	
227	    document.addEventListener('visibilitychange', () => {
228	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
229	    });
230	
231	    reducedMotionQuery.addEventListener('change', (e) => {
232	      manuallyPaused = e.matches;
233	      document.body.classList.toggle('paused', manuallyPaused);
234	      svg.setAttribute('aria-pressed', String(manuallyPaused));
235	      updateLabels();
236	    });
237	
238	    document.body.classList.toggle('paused', manuallyPaused);
239	    svg.setAttribute('aria-pressed', String(manuallyPaused));
240	    updateLabels();
241	  </script>
242	</body>
243	</html>
